.text-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  color: var(--ink);
  font-size: clamp(0.9rem, 0.8rem + 0.4vw, 1.05rem);
}

.text-field__label {
  color: var(--ink);
  font-weight: 600;
}

.text-field__input {
  font: inherit;
  color: var(--ink);
  background: var(--slide);
  border: 1px solid var(--muted);
  border-radius: 0.5rem;
  padding: 0.6em 0.75em;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.text-field__input::placeholder {
  color: var(--muted);
}

/* Focus: add a border colour. The global :focus-visible outline stays in place. */
.text-field__input:focus {
  border-color: var(--myelin);
}

.text-field__input[aria-invalid="true"] {
  border-color: var(--cresyl);
  box-shadow: inset 0 0 0 1px var(--cresyl);
}

.text-field__input[aria-invalid="true"]:focus {
  border-color: var(--cresyl);
}

.text-field__error {
  margin: 0;
  color: var(--cresyl);
  font-size: 0.9em;
  font-weight: 600;
}

:root[data-motion="reduce"] .text-field__input {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .text-field__input {
    transition: none;
  }
}
